  "function_any": {
    title: "An escape-hatch callback slips past the checker",
    expectPython: "passes",
    expectTypescript: "passes",
    runs: false,
    improves: null,
    misuseOf: null,
    python: "\"\"\"`Callable[..., int]` accepts any arguments at all, so a key function that\ntakes the wrong thing still compiles, and fails at run time instead.\"\"\"\n\nfrom collections.abc import Callable\nfrom dataclasses import dataclass\n\n\n@dataclass(frozen=True)\nclass Order:\n    id: str\n    total_cents: int\n\n\ndef cheapest_first(orders: list[Order], key: Callable[..., int]) -> list[Order]:\n    return sorted(orders, key=key)\n\n\ndef demo(orders: list[Order]) -> list[Order]:\n    # The checker accepts this key, and every call of it fails at run time:\n    # an Order has no `[\"total_cents\"]`.\n    return cheapest_first(orders, lambda order, currency: int(order[currency]))\n",
    typescript: "// An `any`-taking callback accepts any arguments at all, so a key function\n// that takes the wrong thing still compiles, and fails at run time instead.\n\ntype Order = { readonly id: string; readonly totalCents: number };\n\nfunction cheapestFirst(orders: Order[], key: (...args: any[]) => number): Order[] {\n  return [...orders].sort((a, b) => key(a) - key(b));\n}\n\nexport function demo(orders: Order[]): Order[] {\n  // The checker accepts this key, and every call of it returns NaN at run\n  // time: an Order has no `[currency]`.\n  return cheapestFirst(orders, (order, currency) => Number(order[currency]));\n}\n",
  },
  "function_values": {
    title: "The parameter type describes the whole callback",
    expectPython: "passes",
    expectTypescript: "passes",
    runs: false,
    improves: "function_any",
    misuseOf: null,
    python: "\"\"\"`key` is a function from Order to int, and `Callable` writes that down.\nThe compiler checks the lambda against it.\"\"\"\n\nfrom collections.abc import Callable\nfrom dataclasses import dataclass\n\n\n@dataclass(frozen=True)\nclass Order:\n    id: str\n    total_cents: int\n\n\ndef cheapest_first(orders: list[Order], key: Callable[[Order], int]) -> list[Order]:\n    return sorted(orders, key=key)\n\n\ndef demo(orders: list[Order]) -> list[Order]:\n    return cheapest_first(orders, lambda order: order.total_cents)\n",
    typescript: "// `key` is a function from Order to number, and the parameter type writes\n// that down. The compiler checks the arrow function against it.\n\ntype Order = {\n  readonly id: string;\n  readonly totalCents: number;\n};\n\nfunction cheapestFirst(orders: Order[], key: (order: Order) => number): Order[] {\n  return [...orders].sort((a, b) => key(a) - key(b));\n}\n\nexport function demo(orders: Order[]): Order[] {\n  return cheapestFirst(orders, (order) => order.totalCents);\n}\n",
  },
  "higher_order": {
    title: "The wrapper keeps the signature it wrapped",
    expectPython: "passes",
    expectTypescript: "passes",
    runs: false,
    improves: "retry_any",
    misuseOf: null,
    python: "\"\"\"`retry` takes a function and returns one with the same parameters and the\nsame result. The type parameters carry the whole signature through.\"\"\"\n\nfrom collections.abc import Callable\n\n\ndef retry[**P, R](times: int, operation: Callable[P, R]) -> Callable[P, R]:\n    def attempt(*args: P.args, **kwargs: P.kwargs) -> R:\n        failures = 0\n        while True:\n            try:\n                return operation(*args, **kwargs)\n            except ConnectionError:\n                failures += 1\n                if failures >= times:\n                    raise\n    return attempt\n\n\ndef fetch(url: str, timeout: int) -> str:\n    return f\"GET {url} within {timeout}s\"\n\n\npatient_fetch = retry(3, fetch)\nresult: str = patient_fetch(\"https://example.test\", 10)\n",
    typescript: "// `retry` takes a function and returns one with the same parameters and the\n// same result. The type parameters carry the whole signature through.\n\nfunction retry<A extends unknown[], R>(\n  times: number,\n  operation: (...args: A) => R,\n): (...args: A) => R {\n  return (...args: A): R => {\n    let failures = 0;\n    for (;;) {\n      try {\n        return operation(...args);\n      } catch (error) {\n        failures += 1;\n        if (failures >= times) throw error;\n      }\n    }\n  };\n}\n\nfunction fetchPage(url: string, timeout: number): string {\n  return `GET ${url} within ${timeout}s`;\n}\n\nconst patientFetch = retry(3, fetchPage);\nexport const result: string = patientFetch(\"https://example.test\", 10);\n",
  },
