  "inline_retry": {
    title: "The retry loop is pasted into the business function",
    expectPython: "passes",
    expectTypescript: "passes",
    runs: false,
    improves: null,
    misuseOf: null,
    python: "\"\"\"The connection policy and the business logic share one body. The next\nfunction that talks to the network pastes the same loop again.\"\"\"\n\n\ndef fetch_greeting(attempts_left: int = 3) -> str:\n    failures = 0\n    while True:\n        try:\n            return unreliable_fetch().upper()\n        except ConnectionError:\n            failures += 1\n            if failures >= attempts_left:\n                raise\n\n\ndef unreliable_fetch() -> str:\n    raise ConnectionError(\"try again\")\n",
    typescript: "// The connection policy and the business logic share one body. The next\n// function that talks to the network pastes the same loop again.\n\nfunction unreliableFetch(): string {\n  throw new Error(\"try again\");\n}\n\nexport function fetchGreeting(attemptsLeft = 3): string {\n  let failures = 0;\n  for (;;) {\n    try {\n      return unreliableFetch().toUpperCase();\n    } catch (error) {\n      failures += 1;\n      if (failures >= attemptsLeft) throw error;\n    }\n  }\n}\n",
  },
  "io_actions": {
    title: "An IO value describes the call, and run performs it",
    expectPython: "passes",
    expectTypescript: "passes",
    runs: true,
    improves: "inline_retry",
    misuseOf: null,
    python: "\"\"\"`IO` wraps a computation without running it. `and_then` composes a larger\ndescription, `retry` wraps any description in a policy, and nothing touches\nthe network until `run`. The retry logic exists once, as a combinator.\"\"\"\n\nfrom collections.abc import Callable\nfrom dataclasses import dataclass\n\n\n@dataclass(frozen=True)\nclass IO[T]:\n    run: Callable[[], T]\n\n\ndef of[T](value: T) -> IO[T]:\n    return IO(lambda: value)\n\n\ndef and_then[T, U](action: IO[T], step: Callable[[T], IO[U]]) -> IO[U]:\n    return IO(lambda: step(action.run()).run())\n\n\ndef retry[T](times: int, action: IO[T]) -> IO[T]:\n    def attempt() -> T:\n        failures = 0\n        while True:\n            try:\n                return action.run()\n            except ConnectionError:\n                failures += 1\n                if failures >= times:\n                    raise\n    return IO(attempt)\n\n\n# A connection that fails twice and then answers, so the retry is observable.\n_calls = {\"count\": 0}\n\n\ndef flaky_fetch() -> str:\n    _calls[\"count\"] += 1\n    if _calls[\"count\"] < 3:\n        raise ConnectionError(\"try again\")\n    return \"payload\"\n\n\ngreeting = and_then(retry(3, IO(flaky_fetch)), lambda text: of(text.upper()))\n\nassert _calls[\"count\"] == 0  # nothing has run yet\nassert greeting.run() == \"PAYLOAD\"\nassert _calls[\"count\"] == 3  # two failures, one answer\n",
    typescript: "// `IO` wraps a computation without running it. `andThen` composes a larger\n// description, `retry` wraps any description in a policy, and nothing touches\n// the network until `run`. The retry logic exists once, as a combinator.\n\ntype IO<T> = { readonly run: () => T };\n\nfunction of<T>(value: T): IO<T> {\n  return { run: () => value };\n}\n\nfunction andThen<T, U>(action: IO<T>, step: (value: T) => IO<U>): IO<U> {\n  return { run: () => step(action.run()).run() };\n}\n\nfunction retry<T>(times: number, action: IO<T>): IO<T> {\n  return {\n    run: () => {\n      let failures = 0;\n      for (;;) {\n        try {\n          return action.run();\n        } catch (error) {\n          failures += 1;\n          if (failures >= times) throw error;\n        }\n      }\n    },\n  };\n}\n\n// A connection that fails twice and then answers, so the retry is observable.\nlet calls = 0;\n\nfunction flakyFetch(): string {\n  calls += 1;\n  if (calls < 3) throw new Error(\"try again\");\n  return \"payload\";\n}\n\nexport const greeting = andThen(retry(3, { run: flakyFetch }), (text) => of(text.toUpperCase()));\n// Nothing has run yet; greeting.run() answers \"PAYLOAD\" on the third call.\n// The Python twin runs these assertions in CI.\n",
  },
  "literal_flag": {
    title: "The signature itself allows two modes",
    expectPython: "passes",
    expectTypescript: "passes",
    runs: false,
    improves: "flag_documented",
    misuseOf: null,
    python: "\"\"\"The docstring used to say \"mode is 'text' or 'binary'\". `Literal` moves that\nsentence into the signature, where the checker reads it.\"\"\"\n\nfrom typing import Literal\n\n\ndef read_log(path: str, mode: Literal[\"text\", \"binary\"]) -> int:\n    record_size = 1 if mode == \"text\" else 8\n    return len(path) * record_size\n\n\ndef tail() -> int:\n    return read_log(\"app.log\", \"binary\")\n",
    typescript: "// The docstring used to say \"mode is 'text' or 'binary'\". A literal union moves\n// that sentence into the signature, where the checker reads it.\n\nexport function readLog(path: string, mode: \"text\" | \"binary\"): number {\n  const recordSize = mode === \"text\" ? 1 : 8;\n  return path.length * recordSize;\n}\n\nexport function tail(): number {\n  return readLog(\"app.log\", \"binary\");\n}\n",
  },
