  "result_chain": {
    title: "A Result carries the reason a step failed",
    expectPython: "passes",
    expectTypescript: "passes",
    runs: true,
    improves: "nullable_chain",
    misuseOf: null,
    python: "\"\"\"The same three steps. `Result` holds a value or a reason, and `and_then`\nchains the steps and stops at the first failure.\"\"\"\n\nfrom collections.abc import Callable\nfrom dataclasses import dataclass\n\n\n@dataclass(frozen=True)\nclass Ok[T]:\n    value: T\n\n\n@dataclass(frozen=True)\nclass Err:\n    reason: str\n\n\ntype Result[T] = Ok[T] | Err\n\n\ndef and_then[T, U](result: Result[T], step: Callable[[T], Result[U]]) -> Result[U]:\n    match result:\n        case Ok(value):\n            return step(value)\n        case Err():\n            return result\n\n\ndef parse_quantity(text: str) -> Result[int]:\n    return Ok(int(text)) if text.isdigit() else Err(f\"not a number: {text!r}\")\n\n\ndef check_stock(quantity: int) -> Result[int]:\n    return Ok(quantity) if quantity <= 10 else Err(\"only 10 in stock\")\n\n\ndef quote(text: str) -> Result[int]:\n    return and_then(and_then(parse_quantity(text), check_stock), lambda q: Ok(q * 250))\n\n\nassert quote(\"3\") == Ok(750)\nassert quote(\"99\") == Err(\"only 10 in stock\")\nassert quote(\"many\") == Err(\"not a number: 'many'\")\n",
    typescript: "// The same three steps. `Result` holds a value or a reason, and `andThen`\n// chains the steps and stops at the first failure.\n\ntype Ok<T> = { readonly kind: \"ok\"; readonly value: T };\ntype Err = { readonly kind: \"err\"; readonly reason: string };\ntype Result<T> = Ok<T> | Err;\n\nfunction ok<T>(value: T): Result<T> {\n  return { kind: \"ok\", value };\n}\n\nfunction err(reason: string): Result<never> {\n  return { kind: \"err\", reason };\n}\n\nfunction andThen<T, U>(result: Result<T>, step: (value: T) => Result<U>): Result<U> {\n  return result.kind === \"ok\" ? step(result.value) : result;\n}\n\nfunction parseQuantity(text: string): Result<number> {\n  return /^\\d+$/.test(text) ? ok(Number(text)) : err(`not a number: ${text}`);\n}\n\nfunction checkStock(quantity: number): Result<number> {\n  return quantity <= 10 ? ok(quantity) : err(\"only 10 in stock\");\n}\n\nexport function quote(text: string): Result<number> {\n  return andThen(andThen(parseQuantity(text), checkStock), (q) => ok(q * 250));\n}\n",
  },
  "retry_any": {
    title: "The wrapper forgets the signature it wrapped",
    expectPython: "passes",
    expectTypescript: "passes",
    runs: false,
    improves: null,
    misuseOf: null,
    python: "\"\"\"`retry` returns `Callable[..., Any]`, so the checker no longer sees the\nparameters or the result of the function inside it.\"\"\"\n\nfrom collections.abc import Callable\nfrom typing import Any\n\n\ndef retry(times: int, operation: Callable[..., Any]) -> Callable[..., Any]:\n    def attempt(*args: Any, **kwargs: Any) -> Any:\n        failures = 0\n        while True:\n            try:\n                return operation(*args, **kwargs)\n            except ConnectionError:\n                failures += 1\n                if failures >= times:\n                    raise\n    return attempt\n\n\ndef fetch(url: str, timeout: int) -> str:\n    return f\"GET {url} within {timeout}s\"\n\n\npatient_fetch = retry(3, fetch)\n# The checker accepts both of these. The second fails at run time.\nfine = patient_fetch(\"https://example.test\", 10)\nwrong = patient_fetch(10, \"https://example.test\")\n",
    typescript: "// `retry` returns an `any`-shaped function, so the checker no longer sees the\n// parameters or the result of the function inside it.\n\nfunction retry(times: number, operation: (...args: any[]) => any): (...args: any[]) => any {\n  return (...args: any[]) => {\n    let failures = 0;\n    for (;;) {\n      try {\n        return operation(...args);\n      } catch (error) {\n        failures += 1;\n        if (failures >= times) throw error;\n      }\n    }\n  };\n}\n\nfunction fetchPage(url: string, timeout: number): string {\n  return `GET ${url} within ${timeout}s`;\n}\n\nconst patientFetch = retry(3, fetchPage);\n// The checker accepts both of these. The second returns nonsense at run time.\nexport const fine = patientFetch(\"https://example.test\", 10);\nexport const wrong = patientFetch(10, \"https://example.test\");\n",
  },
  "status_literal": {
    title: "A literal type lists every status that exists",
    expectPython: "passes",
    expectTypescript: "passes",
    runs: false,
    improves: "status_string",
    misuseOf: null,
    python: "\"\"\"`Literal` lists every value the type allows. The checker rejects the rest.\"\"\"\n\nfrom typing import Literal\n\ntype Status = Literal[\"draft\", \"sent\", \"paid\"]\n\n\ndef advance(status: Status) -> Status:\n    match status:\n        case \"draft\":\n            return \"sent\"\n        case \"sent\":\n            return \"paid\"\n        case \"paid\":\n            return \"paid\"\n",
    typescript: "// A union of string literals lists every value the type allows. The checker\n// rejects the rest.\n\ntype Status = \"draft\" | \"sent\" | \"paid\";\n\nexport function advance(status: Status): Status {\n  switch (status) {\n    case \"draft\":\n      return \"sent\";\n    case \"sent\":\n      return \"paid\";\n    case \"paid\":\n      return \"paid\";\n  }\n}\n",
  },
