    misuseOf: "status_literal",
    python: "\"\"\"The same `advance`, called with a misspelled status.\"\"\"\n\nfrom typing import Literal\n\ntype Status = Literal[\"draft\", \"sent\", \"paid\"]\n\n\ndef advance(status: Status) -> Status:\n    match status:\n        case \"draft\":\n            return \"sent\"\n        case \"sent\":\n            return \"paid\"\n        case \"paid\":\n            return \"paid\"\n\n\ndef submit() -> Status:\n    return advance(\"snet\")  # error: not one of the three statuses\n",
